import sys
from collections import defaultdict

class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.tree = [0] * (4 * n)

    def update(self, idx, val):
        self._update(1, 0, self.n - 1, idx, val)

    def _update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] = max(self.tree[node], val)
            return
        mid = (start + end) // 2
        if start <= idx <= mid:
            self._update(2 * node, start, mid, idx, val)
        else:
            self._update(2 * node + 1, mid + 1, end, idx, val)
        self.tree[node] = max(self.tree[2 * node], self.tree[2 * node + 1])

    def query(self, l, r):
        return self._query(1, 0, self.n - 1, l, r)

    def _query(self, node, start, end, l, r):
        if r < start or end < l:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        p1 = self._query(2 * node, start, mid, l, r)
        p2 = self._query(2 * node + 1, mid + 1, end, l, r)
        return max(p1, p2)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    index = 1
    fogs = []

    for _ in range(n):
        mi = int(data[index])
        di = int(data[index + 1])
        li = int(data[index + 2])
        ri = int(data[index + 3])
        hi = int(data[index + 4])
        delta_di = int(data[index + 5])
        delta_xi = int(data[index + 6])
        delta_hi = int(data[index + 7])
        index += 8

        for k in range(mi):
            day = di + k * delta_di
            left = li + k * delta_xi
            right = ri + k * delta_xi
            height = hi + k * delta_hi
            fogs.append((day, left, right, height))

    fogs.sort()
    max_x = max(fog[2] for fog in fogs)
    st = SegmentTree(max_x + 1)

    missed_fogs = 0
    current_day = 0
    fog_index = 0
    fog_count = len(fogs)

    while fog_index < fog_count:
        if fogs[fog_index][0] > current_day:
            # Calculate missed fogs for the current day
            for x in range(max_x + 1):
                if st.query(x, x) < current_day:
                    missed_fogs += 1
            current_day += 1
        else:
            _, left, right, height = fogs[fog_index]
            for x in range(left, right):
                st.update(x, current_day)
            fog_index += 1

    # Handle any remaining days without new fogs
    while current_day <= fogs[-1][0]:
        for x in range(max_x + 1):
            if st.query(x, x) < current_day:
                missed_fogs += 1
        current_day += 1

    print(missed_fogs)

if __name__ == "__main__":
    main()
